  const path=document.createElementNS(svg.namespaceURI,'polyline');path.setAttribute('points',pts.map(x=>x.join(',')).join(' '));path.setAttribute('fill','none');path.setAttribute('class','chart-line');svg.append(path);
  const labelled=new Set([vals.indexOf(Math.min(...vals)),vals.indexOf(Math.max(...vals)),vals.length-1]);
  pts.forEach(([x,y],i)=>{const c=document.createElementNS(svg.namespaceURI,'circle'),message=`${rows[i].label}: ${number(vals[i])} works`,title=document.createElementNS(svg.namespaceURI,'title');c.setAttribute('cx',x);c.setAttribute('cy',y);c.setAttribute('r','5');c.setAttribute('class','chart-point');c.setAttribute('tabindex','0');c.setAttribute('role','img');c.setAttribute('aria-label',message);title.textContent=message;c.append(title);const year=document.createElementNS(svg.namespaceURI,'text');year.setAttribute('x',x);year.setAttribute('y','274');year.setAttribute('text-anchor','middle');year.setAttribute('class','chart-axis');year.textContent=rows[i].label;svg.append(c,year);if(labelled.has(i)){const val=document.createElementNS(svg.namespaceURI,'text');val.setAttribute('x',x);val.setAttribute('y',Math.max(18,y-12));val.setAttribute('text-anchor',i===0?'start':i===vals.length-1?'end':'middle');val.setAttribute('class','chart-value');val.textContent=number(vals[i]);svg.append(val)}});
