function renderVenues(){const v=venueState;$('venue-type').value=v.work_type||'';bars('source-chart',v.sources,'source',10,v.work_type);bars('publisher-chart',v.publishers,'publisher',10,v.work_type);$('venue-status').textContent=`${number(v.eligible_works)} ${v.work_type||'all-type'} works. A main source is recorded for ${pct(v.source_coverage.percentage)} and its host organisation for ${pct(v.host_coverage.percentage)}.`;const missing=Math.max(0,v.eligible_works-(v.source_coverage.count||0)),named=(v.sources||[]).filter(r=>r.id!=='unknown').slice(0,10).reduce((n,r)=>n+r.count,0),other=Math.max(0,v.eligible_works-missing-named),parts=[['Not recorded',missing,'#bd493d'],['Named in top 10',named,'#34526b'],['Everything else',other,'#c3cbcc']],root=$('venue-concentration'),bar=el('div',null,'coverage-shape'),legend=el('div',null,'coverage-shape-legend');root.replaceChildren(el('strong',`How much of the ${number(v.eligible_works)}-work population the source top 10 represents`));for(const [label,count,colour] of parts){const share=100*count/Math.max(1,v.eligible_works),segment=el('span');segment.style.width=share+'%';segment.style.background=colour;segment.title=`${label}: ${number(count)} works (${pct(share)})`;bar.append(segment);const item=el('span'),swatch=el('i');swatch.style.background=colour;item.append(swatch,document.createTextNode(`${label} · ${pct(share)}`));legend.append(item)}root.append(bar,legend);$('venue-version-note').textContent='The source and publisher lists each scale bars to the largest item in that list; do not compare bar lengths across the two columns. The saved ranking uses OpenAlex’s primary location.';$('venue-note').textContent=v.note}
const renderVenuesWithAbsoluteScale=renderVenues;
renderVenues=function(){renderVenuesWithAbsoluteScale();$('source-chart').querySelector('.missing-line')?.remove();$('venue-version-note').textContent='Every source and publisher bar uses the selected work population as 100%, so lengths are comparable across both columns. The saved ranking uses OpenAlex’s primary location.'};

$('venue-type').addEventListener('change',async()=>{const version=++venueVersion;const p=portrait,type=$('venue-type').value;$('venue-status').textContent='Loading sources and publishers…';$('source-chart').replaceChildren();$('publisher-chart').replaceChildren();try{const params=new URLSearchParams({institution:p.identity.id,start:p.corpus.period.from.slice(0,4),end:p.corpus.period.to.slice(0,4),work_type:type});const result=await api('/api/venues?'+params);if(version!==venueVersion||portrait!==p)return;venueState=result;renderVenues()}catch(e){if(version===venueVersion)$('venue-status').textContent=e.message}});
function affiliationEvidence(target,rows,a){const root=$(target);root.replaceChildren();for(const row of rows.slice(0,12)){const b=el('button',null,'candidate');b.append(el('strong',row.label),el('span',`${number(row.count)} sampled works · inspect →`));b.addEventListener('click',()=>{worksVersion++;worksState=null;$('works-footnote').textContent=`Only works in the saved ${number(a.sampled_works)}-work sample are listed.`;$('works-title').textContent='Affiliation evidence';$('works-meta').textContent=row.label;$('works-list').replaceChildren();for(const work of row.works){const item=el('article',null,'work');item.append(link(work.display_name||'Untitled work',work.id),el('p',String(work.publication_year||'Unknown year')));$('works-list').append(item)}$('page-label').textContent=`${number(row.count)} sampled works`;$('previous').disabled=true;$('next').disabled=true;$('works-dialog').showModal()});root.append(b)}if(!rows.length)root.append(el('p','No matching text was found in this sample.','muted'))}
function renderAffiliations(){const a=portrait.affiliations,core=a.core_names||[],sub=a.sub_affiliations||a.rows;$('affiliation-summary').textContent=`${number(a.mapped_work_coverage.count)} of ${number(a.sampled_works)} sampled works still carry the exact affiliation text OpenAlex used to link them to ${portrait.identity.display_name}.`;$('affiliation-note').textContent='Core names are variants of the institution name. Sub-affiliations are department, faculty or laboratory text from the same affiliation wording; they are not separate institutions or inferred subsidiaries.';$('affiliation-limit').textContent=a.note+` For ${number(a.target_authorships_without_mapped_string)} of ${number(a.observed_target_authorships)} authorships in this sample, OpenAlex did not retain a usable link to the exact affiliation wording.`;affiliationEvidence('affiliation-core',core,a);affiliationEvidence('affiliation-chart',sub,a);const associations=portrait.associated_institutions||[],root=$('association-list');root.replaceChildren();for(const row of associations){const item=el('div',null,'association-row');item.append(link(row.display_name||row.id,row.id),el('strong',row.relationship||'related'));root.append(item)}if(!associations.length)root.append(el('p','No parent, child or related institutions are recorded on this OpenAlex Institution profile.','muted'))}

