async function openResearcher(row){worksVersion++;worksState=null;$('works-title').textContent=row.label;$('works-meta').textContent='Loading researcher details…';$('works-list').replaceChildren();$('page-label').textContent='';$('previous').disabled=true;$('next').disabled=true;$('works-footnote').textContent='Author profiles and affiliations are algorithmically resolved by OpenAlex and can contain errors.';$('works-dialog').showModal();try{const params=new URLSearchParams({institution:portrait.identity.id,author:row.id}),r=await api('/api/researcher-profile?'+params),root=$('works-list');$('works-meta').textContent=`${number(row.count)} profile works in the report period · ${number(r.works_count||0)} career works`;if((r.works_count||0)>10000||(r.first_publication?.publication_year||9999)<1900)root.append(el('p','This profile has implausibly broad dates or output. It may combine several people and should be audited before use.','guidance'));root.append(metric('First covered publication',r.first_publication?.publication_year||'Unknown',r.first_publication?.display_name||'No publication found'),metric('First with this institution',r.first_at_institution?.publication_year||'Unknown',r.first_at_institution?.display_name||'No affiliated publication found'),metric('Distinct Awards linked to their works',(r.award_count_is_lower_bound?'At least ':'')+number(r.award_count),r.note));if(r.orcid)root.append(link('Open ORCID ↗',r.orcid));root.append(el('button','Browse report-period works →','text-button'));root.lastChild.addEventListener('click',()=>openWorks('author',row.id,row.label))}catch(e){$('works-meta').textContent=e.message}}
