const renderFunderGrantOverview=renderFunderReport;
renderFunderReport=function(){renderFunderGrantOverview();const p=portrait,a=p.awards||{},total=a.count||0,amount=a.detailed_count||0,amountShare=total?100*amount/total:0,linkage=a.sample_linkage||{},sample=linkage.sample_size||0,name=p.identity.display_name,current=new Date().getFullYear();$('funder-period').textContent=reportPeriod(p);$('funder-warning').textContent='OpenAlex exposes two funding traces. Direct Award records can link grants to a funder and, when supplied, a lead investigator, recipient institution, and resulting publications. Indirect funding acknowledgements on Works are potential links: they do not prove that each researcher or institution on the Work received the grant. Both traces are incomplete.';$('funder-headline').replaceChildren(metric('Award records',number(total),'Direct OpenAlex Award entities'),metric('Positive amount recorded',pct(amountShare),`${number(amount)} of ${number(total)} Awards`),metric('Linked publications',number(p.population.eligible_works),`${reportPeriod(p)} Work-level links`),metric('Awards in displayed samples',number(sample),'Largest amount and most-linked samples, deduplicated'));const years=(a.start_years||[]).map(r=>({...r,denominator:total,percentage:total?100*r.count/total:0}));staticBars('funder-award-years',years,years.length);$('funder-award-year-note').textContent=`Start year is missing from Awards not represented here. Years after ${current} are scheduled Award dates, not future publications.`;staticBars('funder-currencies',(a.currencies||[]).map(r=>({...r,denominator:amount,percentage:amount?100*r.count/amount:0})),12);$('funder-linkage').replaceChildren(metric('Lead investigator recorded',pct(sample?100*(linkage.with_investigator||0)/sample:0),`${number(linkage.with_investigator||0)} of ${number(sample)} sampled Awards`),metric('Recipient institution recorded',pct(sample?100*(linkage.with_institution||0)/sample:0),`${number(linkage.with_institution||0)} of ${number(sample)} sampled Awards`),metric('Publication link recorded',pct(sample?100*(linkage.with_publications||0)/sample:0),`${number(linkage.with_publications||0)} of ${number(sample)} sampled Awards`));staticBars('funder-domains',p.groups.domains||[],4);staticBars('funder-subfields',p.groups.subfields||[],12);staticBars('funder-topics',p.groups.topics||[],12);const root=$('funder-awards');$('funder-awards-summary').textContent=`OpenAlex has ${number(total)} Award records for ${name}. ${number(amount)} (${pct(amountShare)}) have a recorded positive amount. The lists below show the 25 largest recorded amounts and the 25 Awards linked to the most publications; they are ranked views, not the complete portfolio. ${a.note||''}`;root.replaceChildren();expandableAwards(root,'Largest Awards with a recorded amount',a.detailed_rows,5);expandableAwards(root,'Awards linked to the most publications',a.rows,5);if(!root.children.length)root.append(el('p','No Award records were returned.','muted'));selectFunderSection('funder-overview-panel')};

