const staticBarsWithHelp=staticBars,stackedBarWithHelp=stackedBar;
staticBars=function(target,rows,limit=8,countLabel=null){staticBarsWithHelp(target,rows,limit,countLabel);addWorkTypeHelp(target,rows.slice(0,limit))};
stackedBar=function(target,rows,kind,limit=8,workType=''){stackedBarWithHelp(target,rows,kind,limit,workType);addWorkTypeHelp(target,rows.slice(0,limit))};

